7	import { Box, Text } from 'ink';
8	import { useOverflowState } from '../contexts/OverflowContext.js';
9	import { useStreamingContext } from '../contexts/StreamingContext.js';
10	import { StreamingState } from '../types.js';
11	import { theme } from '../semantic-colors.js';
12	import { useAlternateBuffer } from '../hooks/useAlternateBuffer.js';
13	
14	interface ShowMoreLinesProps {
15	  constrainHeight: boolean;
16	  isOverflowing?: boolean;
17	}
18	
19	export const ShowMoreLines = ({
20	  constrainHeight,
21	  isOverflowing: isOverflowingProp,
22	}: ShowMoreLinesProps) => {
23	  const isAlternateBuffer = useAlternateBuffer();
24	  const overflowState = useOverflowState();
25	  const streamingState = useStreamingContext();
26	
27	  const isOverflowing =
28	    isOverflowingProp ??
29	    (overflowState !== undefined && overflowState.overflowingIds.size > 0);
30	
31	  if (
32	    !isAlternateBuffer ||
33	    !isOverflowing ||
34	    !constrainHeight ||
35	    !(
36	      streamingState === StreamingState.Idle ||
37	      streamingState === StreamingState.WaitingForConfirmation ||
38	      streamingState === StreamingState.Responding
39	    )
40	  ) {
41	    return null;
42	  }
43	
44	  return (
45	    <Box paddingX={1} marginBottom={1}>
46	      <Text color={theme.text.accent} wrap="truncate">
47	        Press Ctrl+O to show more lines
48	      </Text>
49	    </Box>
50	  );
51	};
